 return (zh?'支持来源：':'Supporting sources: ')+list(e.support)+(zh?'；冲突来源：':'; conflicting sources: ')+list(e.conflict)+(e.compatible?.length?(report.kind==='age'?(zh?'；部分重叠的年龄估计：':'; partially overlapping age estimates: '):report.kind==='strength'?(zh?'；部分重叠的军力估计：':'; partially overlapping strength estimates: '):(zh?'；可能并存的人名报告：':'; potentially compatible name reports: '))+list(e.compatible)+(zh?'（不算完全核实）':' (not exact corroboration)'):'')+(e.differentTime?.length?(zh?'；其他日期的报告：':'; reports from other dates: ')+list(e.differentTime)+(zh?'（可能反映局势变化，不计为同时核实或冲突）':' (may reflect change; not same-time corroboration or conflict)'):'')+(e.unattributed?(zh?`；${e.unattributed}份报告缺少可追溯来源，不计为独立证据`:`; ${e.unattributed} report(s) lack traceable origins and do not count independently`):'')+(e.inheritedDispute?(zh?'；转交的原报告已标记为存在争议':' ; a forwarded report already carried a dispute'):'')+(zh?'。同一来源的重复报告只计算一次。':'. Repeated reports from the same source count once.');
